import{readTravel}from'./travel-editor.js';import{discoverGameData,readSpecies}from'./game-data.js';import{STOCK_FIRE_RED_SHA}from'./verified-frlg.js';import{createMovementQuery}from'./world-model.js';import{newScene,prepareScene}from'./authoring-model.js';import{uid}from'./model.js';
export async function prepareRegionStart(reader,sourceId,{enabled=false,giveStarter=true,starterSpecies=[1,4,7]}={}){
 if(!enabled)return null;if(!reader||!sourceId)throw Error('Open a compatible ROM before assigning its new-game start.');readTravel(reader,sourceId);
 if(!giveStarter)return{sourceId,starters:[]};if(!Array.isArray(starterSpecies)||starterSpecies.length<1||starterSpecies.length>3||new Set(starterSpecies).size!==starterSpecies.length||starterSpecies.some(id=>!Number.isInteger(id)||id<1||id>8191))throw Error('Choose one to three different starter species numbers.');
 if(starterSpecies.length>1&&sourceId!==STOCK_FIRE_RED_SHA)throw Error('This ROM needs an answer-menu adapter for a starter choice. Choose one starter, or use the verified FireRed source.');const profile=await discoverGameData(reader,{sourceSha256:sourceId});if(!profile||profile.capabilities?.species===false)throw Error('Starter gifts need a verified Pokémon table.');
 const starters=starterSpecies.map(id=>{if(id>=profile.speciesCount)throw Error('A starter species is outside this ROM.');return{id,name:readSpecies(reader.bytes,profile,id).name};});return{sourceId,starters};
}
export function assignRegionStart(stage,project,map,setup,{level=5}={}){
 if(!setup)return null;const query=createMovementQuery(map),origin=map.generator.exits[0],seen=new Set(),todo=[origin.y*map.width+origin.x],points=[];
 while(todo.length){const i=todo.pop();if(seen.has(i))continue;const x=i%map.width,y=Math.floor(i/map.width),r=query(x,y);if(x<0||y<0||x>=map.width||y>=map.height||r.collision||r.mode==='water')continue;seen.add(i);if(x>3&&y>3&&x<map.width-4&&y<map.height-4&&!map.markers.some(n=>Math.abs(n.x-x)+Math.abs(n.y-y)<3))points.push({x,y,d:Math.abs(x-map.width/2)+Math.abs(y-map.height/2)});if(x)todo.push(i-1);if(x<map.width-1)todo.push(i+1);if(y)todo.push(i-map.width);if(y<map.height-1)todo.push(i+map.width);}
 points.sort((a,b)=>a.d-b.d||a.y-b.y||a.x-b.x);const spawn=points[0];if(!spawn)throw Error('The starting settlement has no safe landing.');stage.travelEdits=structuredClone(project.travelEdits||{});stage.travelEdits[setup.sourceId]??={fly:{},grids:{}};stage.travelEdits[setup.sourceId].spawn={mapId:map.id,x:spawn.x,y:spawn.y};
 // New-game mode owns the initial whiteout destination and the generated
 // Centres' checkpoints, rather than sending a defeated player to Pallet.
 const edit=stage.travelEdits[setup.sourceId];edit.fly[0]={mapId:map.id,x:spawn.x,y:spawn.y};let checkpoint=1;
 for(const room of stage.maps.filter(m=>m.generator?.type==='interior'&&m.generator.kind==='centre'&&(m.generator.floorIndex??0)===0)){
  const door=stage.links.find(l=>l.to.mapId===room.id&&stage.maps.some(m=>m.id===l.from.mapId&&m.generator?.type==='town'));if(!door||checkpoint>=20)continue;
  const queryRoom=createMovementQuery(room),seenRoom=new Set(),queueRoom=[door.to.y*room.width+door.to.x],landings=[];while(queueRoom.length){const i=queueRoom.pop();if(seenRoom.has(i))continue;const x=i%room.width,y=Math.floor(i/room.width),r=queryRoom(x,y);if(x<0||y<0||x>=room.width||y>=room.height||r.collision||r.mode==='water')continue;seenRoom.add(i);if(x>1&&y>1&&x<room.width-2&&y<room.height-2&&!room.markers.some(n=>Math.abs(n.x-x)+Math.abs(n.y-y)<2)&&!stage.links.some(l=>[l.from,l.to].some(e=>e.mapId===room.id&&Math.abs(e.x-x)+Math.abs(e.y-y)<3)))landings.push({x,y,d:Math.abs(x-room.width/2)+Math.abs(y-room.height/2)});if(x)queueRoom.push(i-1);if(x<room.width-1)queueRoom.push(i+1);if(y)queueRoom.push(i-room.width);if(y<room.height-1)queueRoom.push(i+room.width);}
  landings.sort((a,b)=>a.d-b.d);const landing=landings[0]||door.to;edit.fly[checkpoint]={mapId:room.id,x:landing.x,y:landing.y};for(const nurse of room.markers.filter(n=>n.runtime?.steps?.some(s=>s.type==='heal'))){nurse.runtime={...nurse.runtime,action:'scene',repeat:'always',conditions:[],repeatSteps:[],steps:nurse.runtime.steps.flatMap(s=>s.type==='heal'?[s,{type:'respawn',healId:checkpoint+1}]:[s]).map(s=>({id:s.id||uid(),...s}))};}room.generator.respawnId=checkpoint+1;checkpoint++;
 }
 if(setup.starters.length){const event=newScene(stage,spawn.x,spawn.y),gift=s=>({type:'giveMon',species:s.id,level,itemId:0,unlockPartyMenu:setup.sourceId===STOCK_FIRE_RED_SHA});event.title='First partner';Object.assign(event.runtime,{trigger:'enter',repeat:'once',steps:setup.starters.length===1?[gift(setup.starters[0])]:[{id:uid(),type:'answers',text:'Choose your first partner.',allowCancel:false,choices:setup.starters.map(s=>({label:s.name,steps:[gift(s)]})),cancel:[]}]});prepareScene(stage,event);map.markers.push(event);}
 return{mapId:map.id,x:spawn.x,y:spawn.y,starterSpecies:setup.starters.map(s=>s.id),checkpoints:checkpoint};
}
